<script setup>
import { computed,onMounted,ref } from 'vue'
import { apiErrorMessage, showToast } from './uiFeedback'
const apiBase=import.meta.env.VITE_API_BASE||'/api'; const token=localStorage.getItem('support_token')||''; const role=localStorage.getItem('support_role')||''
const id=new URLSearchParams(location.search).get('id'); const admin=computed(()=>role==='admin'); const ticket=ref(null); const history=ref([]); const note=ref(''); const visible=ref(true); const reason=ref(''); const result=ref(''); const progressFiles=ref([]); const receiptFiles=ref([]); const uploading=ref(false); const error=ref('')
function auth(extra={}){return {...extra,Authorization:`Bearer ${token}`}}
async function json(url,options={}){options.headers=auth(options.headers||{}); const r=await fetch(url,options); if(r.status===401){localStorage.removeItem('support_token');location.href='/';throw new Error('登录已失效，请重新登录')} if(!r.ok) throw new Error(await apiErrorMessage(r)); const t=await r.text(); return t?JSON.parse(t):null}
async function load(){try{const list=await json(admin.value?`${apiBase}/admin/tickets`:`${apiBase}/tickets/mine`); ticket.value=list.find(x=>String(x.id)===String(id))||null; history.value=await json(`${apiBase}/tickets/${id}/history`); if(ticket.value){reason.value=ticket.value.resolution_reason||'';result.value=ticket.value.resolution_result||''}}catch(e){error.value=e.message}}
async function uploadFiles(event,target){const files=Array.from(event.target.files||[]); if(!files.length)return; if(target.value.length+files.length>10){showToast('一次最多保留 10 个附件');event.target.value='';return} uploading.value=true; try{for(const file of files){const fd=new FormData();fd.append('file',file);try{target.value.push(await json(`${apiBase}/upload/attachment`,{method:'POST',body:fd}))}catch(e){showToast(`${file.name}：${e.message}`)}}}finally{uploading.value=false;event.target.value=''}}
function removeFile(target,index){target.value.splice(index,1)}
async function add(){if(!note.value.trim()) return showToast('请先填写处理记录'); try{await json(`${apiBase}/admin/tickets/${id}/history`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:note.value,visibleToCustomer:visible.value,attachments:progressFiles.value})}); note.value='';progressFiles.value=[];await load();showToast('处理记录已保存','success')}catch(e){showToast(e.message)}}
async function resolve(){if(!reason.value.trim()||!result.value.trim()) return showToast('请填写原因和处理结果'); try{await json(`${apiBase}/admin/tickets/${id}/resolve`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({resolutionReason:reason.value,resolutionResult:result.value,attachments:receiptFiles.value})});receiptFiles.value=[];await load();showToast('解决回执已保存','success')}catch(e){showToast(e.message)}}
function actionText(v){return {progress:'处理记录',resolved:'已解决',created:'已提交'}[v]||v}
function time(v){return v?String(v).replace('T',' ').slice(0,19):'-'}
function size(v){const n=Number(v||0);if(n<1024)return `${n} B`;if(n<1048576)return `${(n/1024).toFixed(1)} KB`;return `${(n/1048576).toFixed(1)} MB`}
function isVideo(file){return String(file.content_type||'').startsWith('video/')||/\.(mp4|mov|avi|mkv|webm)$/i.test(file.original_name||file.name||'')}
onMounted(load)
</script>
<template><main class="page"><header><div><span>MYROBOOT SUPPORT</span><h1>工单 #{{id}} 处理详情</h1></div><a :href="admin?'/admin':'/'">返回</a></header><div v-if="error" class="error">{{error}}</div><section v-if="ticket" class="panel"><div class="head"><div><b>{{ticket.category||'技术问题'}}</b><small>{{time(ticket.create_time)}}</small></div><strong>{{ticket.status}}</strong></div><p class="desc">{{ticket.description}}</p><img v-if="ticket.screenshot_url" :src="ticket.screenshot_url" class="shot"/><div v-if="ticket.attachments?.length" class="attachments"><h3>客户提交附件</h3><a v-for="file in ticket.attachments" :key="file.id" :href="file.file_url" target="_blank"><span>{{file.original_name}}</span><small>{{size(file.file_size)}}</small></a></div></section><section class="panel"><h2>处理时间线</h2><div v-if="!history.length" class="empty">暂无处理记录</div><div v-for="item in history" :key="item.id" class="timeline"><i></i><div><div class="meta"><b>{{actionText(item.action_type)}}</b><span>{{item.operator_name||'系统'}} · {{time(item.create_time)}}</span></div><p>{{item.content}}</p><div v-if="item.attachments?.length" class="history-files"><template v-for="f in item.attachments" :key="f.id"><video v-if="isVideo(f)" :src="f.file_url" controls preload="metadata"></video><a :href="f.file_url" target="_blank">{{f.original_name}} <small>{{size(f.file_size)}}</small></a></template></div><small v-if="admin&&item.visible_to_customer===0">仅管理员可见</small></div></div></section><template v-if="admin"><section class="panel"><h2>新增处理记录</h2><textarea v-model="note" rows="5" placeholder="记录排查过程、客户配合事项、当前进展"></textarea><label class="check"><input v-model="visible" type="checkbox"/> 对客户可见</label><label class="upload">处理附件<input type="file" multiple @change="uploadFiles($event,progressFiles)"/><small>支持图片、Office、PDF、压缩包、日志和视频</small></label><div v-if="progressFiles.length" class="pending-files"><div v-for="(f,i) in progressFiles" :key="f.url"><span>{{f.name}}</span><button @click="removeFile(progressFiles,i)">移除</button></div></div><button :disabled="uploading" @click="add">保存处理记录</button></section><section class="panel"><h2>解决回执</h2><label>具体原因<textarea v-model="reason" rows="4"/></label><label>处理结果<textarea v-model="result" rows="5"/></label><label class="upload">回执附件<input type="file" multiple @change="uploadFiles($event,receiptFiles)"/><small>可上传验收截图、Excel、PDF、Word、压缩包、操作视频等</small></label><div v-if="receiptFiles.length" class="pending-files"><div v-for="(f,i) in receiptFiles" :key="f.url"><span>{{f.name}}</span><button @click="removeFile(receiptFiles,i)">移除</button></div></div><button class="primary" :disabled="uploading" @click="resolve">保存并标记已解决</button></section></template></main></template>
<style scoped>.page{max-width:900px;margin:auto;padding:34px 20px 70px;background:#f4f7fb;min-height:100vh}header{background:#10243e;color:#fff;border-radius:20px;padding:28px;display:flex;justify-content:space-between;align-items:center}header span{font-size:12px;letter-spacing:1.4px;opacity:.7}header h1{margin:8px 0}header a{color:#fff;text-decoration:none;border:1px solid #ffffff40;padding:9px 13px;border-radius:8px}.panel{background:#fff;border:1px solid #e2e8f0;border-radius:16px;padding:22px;margin-top:16px}.head{display:flex;justify-content:space-between}.head small{display:block;color:#8391a3;margin-top:5px}.desc{white-space:pre-wrap;line-height:1.7}.shot{max-width:320px;max-height:240px;border-radius:10px;border:1px solid #e5eaf0}.attachments,.history-files{display:grid;gap:8px;margin-top:16px}.attachments h3{margin:0 0 3px}.attachments a,.history-files a{display:flex;justify-content:space-between;gap:15px;text-decoration:none;border:1px solid #e2e8f0;background:#f9fbfd;border-radius:9px;padding:10px 12px;color:#33465f}.attachments small,.history-files small{color:#8290a3}.history-files video{width:100%;max-height:360px;border-radius:10px;background:#111}.timeline{display:grid;grid-template-columns:18px 1fr;gap:12px;padding:12px 0}.timeline i{width:10px;height:10px;border-radius:50%;background:#245eea;margin-top:6px;box-shadow:0 0 0 5px #edf3ff}.timeline>div{border-bottom:1px solid #eef2f6;padding-bottom:14px}.meta{display:flex;justify-content:space-between;gap:15px}.meta span{color:#8795a7;font-size:13px}.timeline p{white-space:pre-wrap;line-height:1.7}.timeline>div>small{color:#a16a00}textarea{width:100%;border:1px solid #d7dfeb;border-radius:9px;padding:11px;box-sizing:border-box;margin:8px 0 12px}label{display:grid;gap:6px;margin-top:12px}.check{display:flex;align-items:center;gap:8px}.upload input{border:1px dashed #bccbe0;border-radius:10px;padding:12px;background:#f8faff}.upload small{color:#8593a6}.pending-files{display:grid;gap:8px;margin:12px 0}.pending-files>div{display:flex;justify-content:space-between;gap:12px;align-items:center;border:1px solid #e2e8f0;background:#f9fbfd;border-radius:9px;padding:9px 11px}.pending-files button{background:#fff0f0;color:#b42318;padding:6px 9px}button{border:0;border-radius:9px;padding:10px 15px;background:#eef2f7}.primary{background:#245eea;color:#fff}.error{margin-top:16px;padding:12px;background:#fff1f0;color:#b42318;border-radius:9px}.empty{color:#8795a7}@media(max-width:600px){.attachments a,.history-files a{display:grid}.meta{display:grid}}</style>
